"""Getting structured data out of model output without trusting it.

Two jobs: find the JSON in a reply that may be wrapped in prose or fences, and
coerce whatever came back into `ItemInference` without ever raising. A malformed
reply must degrade one item, never lose the round.
"""

from __future__ import annotations

import json
import math
from collections.abc import Mapping, Sequence
from typing import Any

from app.c2f.models import ItemInference, LineItem, PriceQuantiles
from app.c2f.probability.survival import quantiles_from_median

#: Used when the validity call fails outright. Deliberately just above the 2/3
#: bar: a blanket `b = 0` would pay the 1.5x lawyer penalty to every opponent on
#: every genuinely covered item, which is the most expensive way to be wrong.
DEFAULT_P_VALID: float = 0.75
#: Used when the pricing call fails. Wide on purpose - honest uncertainty pushes
#: the charge up and the acceptance limit down, which is the safe direction on
#: both sides.
FALLBACK_MEDIAN: float = 200.0
FALLBACK_SIGMA_LOG: float = 1.2


def extract_json(text: str) -> Any | None:
    """First complete JSON object or array in `text`, or None.

    Handles ```json fences, leading commentary, and trailing prose. Brace
    counting is string-aware so a `{` inside an evidence string cannot throw off
    the balance.
    """
    if not text:
        return None

    for opener, closer in (("{", "}"), ("[", "]")):
        start = text.find(opener)
        while start != -1:
            depth = 0
            in_string = False
            escaped = False
            for index in range(start, len(text)):
                char = text[index]
                if in_string:
                    if escaped:
                        escaped = False
                    elif char == "\\":
                        escaped = True
                    elif char == '"':
                        in_string = False
                    continue
                if char == '"':
                    in_string = True
                elif char == opener:
                    depth += 1
                elif char == closer:
                    depth -= 1
                    if depth == 0:
                        try:
                            return json.loads(text[start : index + 1])
                        except json.JSONDecodeError:
                            break
            start = text.find(opener, start + 1)
    return None


def _as_probability(value: Any, default: float) -> float:
    """Coerce to [0, 1]. Accepts percentages, which models emit unprompted."""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    if not math.isfinite(number):
        return default
    if number > 1.0:
        number = number / 100.0 if number <= 100.0 else 1.0
    return min(max(number, 0.0), 1.0)


def _as_float(value: Any, default: float) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    return number if math.isfinite(number) else default


def index_by_item(payload: Any) -> dict[str, Mapping[str, Any]]:
    """Normalise a reply into `{item_id: fields}`.

    Accepts the three shapes models actually return: a top-level list, a dict
    with an `items` list, or a dict keyed directly by item id.
    """
    if isinstance(payload, Mapping):
        for key in ("items", "line_items", "results"):
            inner = payload.get(key)
            if isinstance(inner, Sequence) and not isinstance(inner, str | bytes):
                payload = inner
                break
        else:
            if all(isinstance(v, Mapping) for v in payload.values()) and payload:
                return {str(k): v for k, v in payload.items()}  # type: ignore[misc]
            payload = [payload]

    if not isinstance(payload, Sequence) or isinstance(payload, str | bytes):
        return {}

    out: dict[str, Mapping[str, Any]] = {}
    for position, entry in enumerate(payload):
        if not isinstance(entry, Mapping):
            continue
        raw_id = entry.get("item_id", entry.get("id", entry.get("line", position + 1)))
        out[str(raw_id).strip()] = entry
    return out


def fallback_inference(item: LineItem, *, reason: str = "inference unavailable") -> ItemInference:
    """A wide, mildly-confident belief. Never blocks a submission."""
    return ItemInference(
        item_id=item.item_id,
        p_valid=DEFAULT_P_VALID,
        unit_quantiles=quantiles_from_median(FALLBACK_MEDIAN, FALLBACK_SIGMA_LOG),
        evidence=reason,
        degraded=True,
    )


def merge_inferences(
    items: Sequence[LineItem],
    validity: Mapping[str, Mapping[str, Any]],
    pricing: Mapping[str, Mapping[str, Any]],
    skeptic: Mapping[str, Mapping[str, Any]] | None = None,
) -> list[ItemInference]:
    """One `ItemInference` per parsed line item, in invoice order.

    Every item gets an entry even when a call dropped it, because the submission
    is rejected outright if an item is missing.
    """
    skeptic = skeptic or {}
    out: list[ItemInference] = []

    for item in items:
        item_id = item.item_id
        validity_row = validity.get(item_id)
        pricing_row = pricing.get(item_id)

        if validity_row is None and pricing_row is None:
            out.append(fallback_inference(item, reason="no model output for this item"))
            continue

        p_valid = _as_probability(
            (validity_row or {}).get("p_valid"),
            DEFAULT_P_VALID,
        )

        degraded = False
        if pricing_row is None:
            quantiles = quantiles_from_median(FALLBACK_MEDIAN, FALLBACK_SIGMA_LOG)
            degraded = True
        else:
            try:
                quantiles = PriceQuantiles.from_mapping(pricing_row)
            except (ValueError, TypeError):
                median = _as_float(pricing_row.get("q50", pricing_row.get("median")), 0.0)
                quantiles = quantiles_from_median(median or FALLBACK_MEDIAN, FALLBACK_SIGMA_LOG)
                degraded = True

        skeptic_row = skeptic.get(item_id) or {}
        multiplier = _as_float(
            skeptic_row.get("suggested_multiplier", skeptic_row.get("multiplier")), 1.0
        )

        out.append(
            ItemInference(
                item_id=item_id,
                p_valid=p_valid,
                unit_quantiles=quantiles,
                p_covered=_as_probability((validity_row or {}).get("p_covered"), float("nan"))
                if validity_row and "p_covered" in validity_row
                else None,
                p_related=_as_probability((validity_row or {}).get("p_related"), float("nan"))
                if validity_row and "p_related" in validity_row
                else None,
                skeptic_multiplier=multiplier,
                evidence=str((validity_row or {}).get("evidence", ""))[:600],
                confidence=str((pricing_row or {}).get("confidence", "")),
                degraded=degraded,
            )
        )
    return out

"""The semantic layer. Every test here is a way a real reply goes wrong."""

from __future__ import annotations

import asyncio
import json

import pytest

from app.c2f.inference.analyse import CaseBundle, analyse_case, heuristic_inferences
from app.c2f.inference.schemas import (
    DEFAULT_P_VALID,
    extract_json,
    index_by_item,
    merge_inferences,
)
from app.c2f.models import LineItem
from app.llm.base import Completion

ITEMS = [
    LineItem(item_id="1", description="Windschutzscheibe", quantity=1.0),
    LineItem(item_id="2", description="Arbeitszeit Monteur", quantity=3.5, unit="h"),
]


def validity_payload() -> list[dict]:
    return [
        {"item_id": "1", "p_valid": 0.96, "p_covered": 0.98, "p_related": 0.97, "evidence": "e"},
        {"item_id": "2", "p_valid": 0.9, "evidence": "labour follows the glass"},
    ]


def pricing_payload() -> list[dict]:
    return [
        {"item_id": "1", "q10": 280, "q25": 340, "q50": 430, "q75": 540, "q90": 680},
        {"item_id": "2", "q10": 60, "q25": 70, "q50": 85, "q75": 100, "q90": 130},
    ]


class ScriptedProvider:
    """Returns a canned reply per system prompt, so calls stay distinguishable."""

    name = "scripted"
    model = "scripted-1"

    def __init__(self, replies: dict[str, str | Exception], *, delay: float = 0.0) -> None:
        self.replies = replies
        self.delay = delay
        self.seen: list[str] = []

    async def complete(self, messages, *, system=None, max_tokens=16_000) -> Completion:
        which = self._which(system or "")
        self.seen.append(which)
        if self.delay:
            await asyncio.sleep(self.delay)
        reply = self.replies.get(which, "")
        if isinstance(reply, Exception):
            raise reply
        if reply == "__refused__":
            return Completion(content="declined", model=self.model, refused=True)
        return Completion(content=reply, model=self.model)

    async def stream(self, messages, *, system=None, max_tokens=64_000):  # pragma: no cover
        yield ""
        raise NotImplementedError

    @staticmethod
    def _which(system: str) -> str:
        if "claims examiner" in system:
            return "validity"
        if "repair-cost assessor" in system:
            return "pricing"
        return "skeptic"


def bundle() -> CaseBundle:
    return CaseBundle(
        case_id="0",
        items=list(ITEMS),
        policy="Comprehensive glass cover applies.",
        description="Stone chip cracked the windshield on the A9.",
    )


# ---------- extract_json ----------


@pytest.mark.parametrize(
    "text",
    [
        '[{"item_id": "1", "p_valid": 0.9}]',
        'Sure!\n```json\n[{"item_id": "1", "p_valid": 0.9}]\n```\nHope that helps.',
        'Here you go: [{"item_id": "1", "p_valid": 0.9}] - let me know.',
        '{"items": [{"item_id": "1", "p_valid": 0.9}]}',
    ],
)
def test_extract_json_survives_prose_and_fences(text):
    payload = extract_json(text)
    assert payload is not None
    assert index_by_item(payload)["1"]["p_valid"] == 0.9


def test_extract_json_is_string_aware():
    """A brace inside an evidence string must not unbalance the scan."""
    text = '[{"item_id": "1", "evidence": "clause {3} says \\"covered\\"", "p_valid": 0.8}]'
    assert index_by_item(extract_json(text))["1"]["p_valid"] == 0.8


@pytest.mark.parametrize("text", ["", "no json here", "{unclosed", "[1, 2,"])
def test_extract_json_returns_none_rather_than_raising(text):
    assert extract_json(text) is None


def test_extract_json_skips_a_broken_object_and_finds_the_next():
    assert extract_json('{"bad": } {"item_id": "1"}') == {"item_id": "1"}


# ---------- index_by_item ----------


def test_index_by_item_accepts_the_three_shapes_models_return():
    rows = [{"item_id": "1", "p_valid": 0.9}]
    as_list = index_by_item(rows)
    as_wrapped = index_by_item({"items": rows})
    as_keyed = index_by_item({"1": {"p_valid": 0.9}})
    assert as_list["1"]["p_valid"] == as_wrapped["1"]["p_valid"] == as_keyed["1"]["p_valid"]


def test_index_by_item_falls_back_to_position_when_ids_are_dropped():
    assert set(index_by_item([{"p_valid": 0.9}, {"p_valid": 0.8}])) == {"1", "2"}


def test_index_by_item_ignores_junk():
    assert index_by_item("nope") == {}
    assert index_by_item([1, 2, 3]) == {}


# ---------- merge ----------


def test_merge_produces_one_inference_per_item_in_order():
    merged = merge_inferences(ITEMS, index_by_item(validity_payload()), index_by_item(pricing_payload()))
    assert [i.item_id for i in merged] == ["1", "2"]
    assert merged[0].p_valid == 0.96
    assert merged[0].unit_quantiles.q50 == 430.0
    assert not any(i.degraded for i in merged)


def test_merge_covers_an_item_the_model_dropped():
    """A missing item invalidates the whole submission, so it always gets a row."""
    partial = index_by_item([pricing_payload()[0]])
    merged = merge_inferences(ITEMS, index_by_item(validity_payload()), partial)
    assert len(merged) == 2
    assert merged[1].degraded
    assert merged[1].p_valid == 0.9  # validity survived even though pricing did not


def test_merge_defaults_p_valid_above_the_two_thirds_bar():
    """A blanket b=0 would pay the 1.5x penalty on every covered item."""
    merged = merge_inferences(ITEMS, {}, index_by_item(pricing_payload()))
    assert all(i.p_valid == DEFAULT_P_VALID for i in merged)
    assert DEFAULT_P_VALID > 2 / 3


def test_merge_accepts_percentages():
    rows = index_by_item([{"item_id": "1", "p_valid": 96}, {"item_id": "2", "p_valid": 90}])
    merged = merge_inferences(ITEMS, rows, index_by_item(pricing_payload()))
    assert merged[0].p_valid == pytest.approx(0.96)


def test_merge_repairs_a_partial_quantile_ladder():
    rows = index_by_item([{"item_id": "1", "q50": 400}, {"item_id": "2", "q50": 90}])
    merged = merge_inferences(ITEMS, index_by_item(validity_payload()), rows)
    assert merged[0].unit_quantiles.q50 == pytest.approx(400.0)
    assert merged[0].degraded  # we invented the spread, so say so
    assert merged[0].unit_quantiles.q10 < merged[0].unit_quantiles.q90


def test_merge_clamps_a_skeptic_that_argues_prices_up():
    skeptic = index_by_item([{"item_id": "1", "suggested_multiplier": 2.5}])
    merged = merge_inferences(
        ITEMS, index_by_item(validity_payload()), index_by_item(pricing_payload()), skeptic
    )
    # Stored raw; the clamp to [0.5, 1.0] is applied when the distribution is built.
    assert merged[0].skeptic_multiplier == 2.5


